html:
{{ letter_head }}

{% set company_addr = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = frappe.get_doc("Address", company_addr) if company_addr else None %}

<style>
.cgm-inv { font-family: Arial, sans-serif; color: #171717; font-size: 11px; }
.cgm-inv h1 { margin: 0; font-size: 22px; font-weight: 900; letter-spacing: 1px; }

.cgm-meta { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
.cgm-meta td { vertical-align: top; padding: 2px 0; }

.cgm-parties { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
.cgm-parties td { vertical-align: top; width: 50%; padding: 4px 8px 4px 0; }
.cgm-parties .label { color: #8b1a1a; font-weight: 700; font-size: 11px; margin-bottom: 4px; }
.cgm-parties .name { font-weight: 700; margin-bottom: 2px; }
.cgm-parties .addr { font-size: 10px; line-height: 1.5; }

.cgm-bar { width: 100%; border-collapse: collapse; margin: 10px 0; table-layout: fixed; }
.cgm-bar th, .cgm-bar td {
  border: 1px solid #ccc; padding: 6px 8px;
  font-size: 10px; text-align: left; vertical-align: middle;
}
.cgm-bar tr.bar-red th, .cgm-bar tr.bar-red td {
  background: #8b1a1a; color: #fff; border-color: #8b1a1a;
}
.cgm-bar tr.bar-red th { font-weight: 700; width: 12%; }
.cgm-bar tr.bar-red td { font-weight: 400; width: 21.33%; }
.cgm-bar tr.bar-white th, .cgm-bar tr.bar-white td {
  background: #fff; color: #171717; font-weight: 400;
}
.cgm-bar tr.bar-white th { font-weight: 700; width: 12%; }
.cgm-bar tr.bar-white td { width: 21.33%; }

.cgm-items { width: 100%; border-collapse: collapse; margin-top: 8px; }
.cgm-items thead tr th {
  background: #8b1a1a; color: #fff;
  padding: 7px 8px; text-align: left; font-size: 10px;
}
.cgm-items thead tr th.num { text-align: right; }
.cgm-items tbody tr td {
  border-bottom: 1px solid #ececec; padding: 6px 8px;
  font-size: 10px; vertical-align: top;
}
.cgm-items tbody tr td.num { text-align: right; white-space: nowrap; }
.cgm-items tbody tr:nth-child(even) td { background: #fafafa; }
.cgm-items tbody tr.empty-row td { height: 20px; border-bottom: 1px solid #ececec; }

.cgm-footer { width: 100%; border-collapse: collapse; margin-top: 14px; table-layout: fixed; }
.cgm-footer > tbody > tr > td { vertical-align: top; padding: 0; }

.cgm-terms-box {
  border: 1px solid #171717; padding: 10px 12px;
  font-size: 10px; line-height: 1.6;
}

/* QR box — table layout, wkhtmltopdf compatible */
.cgm-qr-box {
  margin-top: 10px;
  border: none;
  background: none;
  border-collapse: collapse;
}
.cgm-qr-box td {
  vertical-align: top;
  padding: 0;
}
.cgm-qr-box .qr-img-cell {
  width: 200px;
}
.cgm-qr-box img,
.cgm-qr-box svg {
  display: block;
  width: 200px;
  height: 200px;
}

.cgm-totals-box { border: 1px solid #171717; width: 100%; border-collapse: collapse; }
.cgm-totals-box td { padding: 8px 10px; font-size: 11px; border-bottom: 1px solid #ccc; }
.cgm-totals-box .t-label { font-weight: 700; width: 50%; }
.cgm-totals-box .t-value { text-align: right; font-weight: 700; }
.cgm-totals-box tr:last-child td { border-bottom: none; }

.cgm-thanks-box {
  border: 2px solid #171717; padding: 14px 10px;
  font-size: 18px; font-weight: 800; text-align: center;
  margin-top: 14px;
}

.text-right { text-align: right; }
.in-words { font-size: 10px; margin-top: 6px; }
</style>

<div class="cgm-inv">

  <!-- INVOICE heading + meta -->
  <table class="cgm-meta">
    <tr>
      <td style="width:55%"><h1>INVOICE</h1></td>
      <td class="text-right" style="font-size:10px; line-height:1.8;">
        <strong>Date:</strong> {{ frappe.utils.format_date(doc.posting_date, "dd-MM-yyyy") }}&nbsp;&nbsp;
        <strong>Invoice No:</strong> {{ doc.name }}<br>
        {% if doc.due_date %}
        <strong>Due Date:</strong> {{ frappe.utils.format_date(doc.due_date, "dd-MM-yyyy") }}
        {% endif %}
      </td>
    </tr>
  </table>

  <!-- Consignee / Invoice Address -->
  <table class="cgm-parties">
    <tr>
      <td>
        <div class="label">Consignee Address</div>
        <div class="name">{{ doc.customer_name }}</div>
        <div class="addr">
          {% if doc.custom_consignee_address %}
            {{ doc.custom_consignee_address | replace("\n", "<br>") }}
          {% elif doc.address_display %}
            {{ doc.address_display }}
          {% endif %}
        </div>
      </td>
      <td>
        <div class="label">Invoice Address</div>
        <div class="name">{{ doc.company }}</div>
        <div class="addr">
          {% if company_address %}
            {% if company_address.address_line1 %}{{ company_address.address_line1 }}<br>{% endif %}
            {% if company_address.address_line2 %}{{ company_address.address_line2 }}<br>{% endif %}
            {% if company_address.city %}{{ company_address.city }}{% if company_address.pincode %} - {{ company_address.pincode }}{% endif %}<br>{% endif %}
            {% if company_address.country %}{{ company_address.country }}<br>{% endif %}
            {% if company_address.phone %}Phone: {{ company_address.phone }}{% endif %}
          {% elif doc.company_address_display %}
            {{ doc.company_address_display }}
          {% endif %}
        </div>
      </td>
    </tr>
  </table>

  <!-- Shipment bar -->
  <table class="cgm-bar">
    <tr class="bar-red">
      <th>Shipment</th>
      <td>{{ doc.project or "" }}</td>
      <th>C.O.O</th>
      <td>{{ doc.custom_country_of_origin or "" }}</td>
      <th>Due Date</th>
      <td>{% if doc.due_date %}{{ frappe.utils.format_date(doc.due_date, "dd-MM-yyyy") }}{% endif %}</td>
    </tr>
    <tr class="bar-white">
      <th>Our Ref No:</th>
      <td>{{ doc.custom_cgm_reference_no or "" }}</td>
      <th>IDF No:</th>
      <td>{{ doc.custom_idfno or "" }}</td>
      <th>Client Ref No:</th>
      <td>{{ doc.custom_client_reference_no or "" }}</td>
    </tr>
  </table>

  <!-- Items -->
  <table class="cgm-items">
    <thead>
      <tr>
        <th style="width:52%">Item Descriptions</th>
        <th class="num" style="width:12%">Qty</th>
        <th class="num" style="width:18%">Rate</th>
        <th class="num" style="width:18%">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td>{{ item.description or item.item_name }}</td>
        <td class="num">{{ item.get_formatted("qty", doc) }}</td>
        <td class="num">{{ item.get_formatted("rate", doc) }}</td>
        <td class="num">{{ item.get_formatted("amount", doc) }}</td>
      </tr>
      {% endfor %}
      {% set filled = doc.items | length %}
      {% for i in range([8 - filled, 0] | max) %}
      <tr class="empty-row"><td></td><td></td><td></td><td></td></tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- Generate QR once, reuse below -->
  {%- set _ns = namespace(qr_b64=None) %}
  {%- if get_doc_qr_code is defined and get_doc_qr_code is callable %}
    {%- set _ns.qr_b64 = get_doc_qr_code(doc.doctype, doc.name) %}
  {%- endif %}

  <!-- Footer: Terms + QR left | Totals right -->
  <table class="cgm-footer">
    <tr>
      <td style="width:50%; padding-right:8px; vertical-align:top;">

        <!-- Terms -->
        <div class="cgm-terms-box">
          <strong>Terms:</strong><br>
          {% if doc.terms %}
            {{ doc.terms }}
          {% else %}
            1: Invoice Due On Receipt.<br>
            2: Reimbursement &amp; Refunds to be paid as Communicated on Email.<br>
            3: All Cheques / RTGS/EFTs are payable to :<br>
            &nbsp;&nbsp;Account Name: CGM Worldwide Shipping Company Limited.<br>
            &nbsp;&nbsp;Account Number: (KES) 5258060018<br>
            &nbsp;&nbsp;Bank Name: NCBA BANK<br>
            &nbsp;&nbsp;Branch Name: KENYATTA AVENUE<br>
            &nbsp;&nbsp;Swift Code: CBAFKENX
          {% endif %}
        </div>

        <!-- QR Code below terms -->
        <table class="cgm-qr-box">
          <tr>
            <td class="qr-img-cell" style="width:200px;">
              {% if _ns.qr_b64 %}
                <img src="data:image/png;base64,{{ _ns.qr_b64 }}"
                     width="200" height="200" alt="Scan to verify"
                     style="display:block; width:200px; height:200px;">
              {% else %}
                <svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 80 80" style="display:block; width:200px; height:200px;">
                  <rect width="80" height="80" fill="white" stroke="#e0e0e0" stroke-width="0.5"/>
                  <rect x="4"  y="4"  width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
                  <rect x="9"  y="9"  width="18" height="18" fill="#8b1a1a" rx="1"/>
                  <rect x="48" y="4"  width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
                  <rect x="53" y="9"  width="18" height="18" fill="#8b1a1a" rx="1"/>
                  <rect x="4"  y="48" width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
                  <rect x="9"  y="53" width="18" height="18" fill="#8b1a1a" rx="1"/>
                  <rect x="40" y="40" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="49" y="40" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="58" y="40" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="67" y="40" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="40" y="49" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="58" y="49" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="40" y="58" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="49" y="58" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="67" y="58" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="40" y="67" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="58" y="67" width="6" height="6" fill="#8b1a1a"/>
                  <rect x="67" y="67" width="6" height="6" fill="#8b1a1a"/>
                </svg>
              {% endif %}
            </td>

          </tr>
        </table>

      </td>
      <td style="width:50%; vertical-align:top;">
        <table class="cgm-totals-box">
          <tr>
            <td class="t-label">Subtotal</td>
            <td class="t-value">{{ doc.get_formatted("net_total") }}</td>
          </tr>
          {% set vat_shown = false %}
          {% for tax in doc.taxes or [] %}
            {% if tax.tax_amount %}
            <tr>
              <td class="t-label">{{ tax.description or "VAT" }}</td>
              <td class="t-value">{{ tax.get_formatted("tax_amount") }}</td>
            </tr>
            {% set vat_shown = true %}
            {% endif %}
          {% endfor %}
          {% if not vat_shown %}
          <tr>
            <td class="t-label">VAT</td>
            <td class="t-value"></td>
          </tr>
          {% endif %}
          <tr>
            <td class="t-label">Total</td>
            <td class="t-value">{{ doc.get_formatted("grand_total") }}</td>
          </tr>
        </table>
        {% if doc.in_words %}
        <p class="in-words"><strong>In Words:</strong> {{ doc.in_words }}</p>
        {% endif %}
      </td>
    </tr>
  </table>

  <!-- Thank you -->
  <div class="cgm-thanks-box">Thank you for your business.</div>

</div>

{%- if footer -%}{{ footer }}{%- endif -%}
